import p0_q3_discovery as d
from p0_common import read_csv, ts
r = [x for x in read_csv("sample_deletion_requests.csv") if x["case_id"] == "case_17"][0]
uid, vals = d.subject(r["email"], ts(r["audit_at"]))
for f in d.eligible_files(ts(r["audit_at"])):
    for rec in d.RECS[f]:
        if ("account_6523" in rec or "account_4092" in rec) and d.hit(rec, vals):
            print(f, d.man[f]["captured_at"][:10], rec.replace("\n", " | ")[:330])
EOF

